      { ts: 1000, seq: 0, type: 'session.start', session_id: sessionId, data: { iteration: 1 } },
      {
        ts: 2000, seq: 1, type: 'session.update', session_id: sessionId,
        data: {
          iteration: 1,
          update: {
            sessionUpdate: 'tool_call',
            rawInput: { command: 'kspec task start @task-1' },
