      {
        ts: 4000, seq: 3, type: 'session.update', session_id: sessionId,
        data: {
          iteration: 2,
          update: {
            sessionUpdate: 'tool_call',
            rawInput: { command: 'kspec task complete @task-1 --reason "Done"' },
