    await fs.rm(sessionsDir, { recursive: true });
    await fs.mkdir(sessionsDir);

    const sessions = kspecJson<SessionLogSummary[]>('session log list', tempDir);
    expect(sessions).toEqual([]);
  });

  // AC: @session-log-list ac-7
