  it('should group by week correctly', () => {
    const summaries: SessionLogSummary[] = [
      {
        id: 'session-1',
        status: 'completed',
        agent_type: 'claude-code-acp',
        started_at: '2026-01-20T10:00:00.000Z', // Week 4
        duration_ms: 3600000,
        event_count: 100,
        iteration_count: 3,
        tasks_completed: 2,
      },
      {
        id: 'session-2',
        status: 'completed',
        agent_type: 'claude-code-acp',
        started_at: '2026-01-27T10:00:00.000Z', // Week 5
        duration_ms: 7200000,
        event_count: 200,
        iteration_count: 5,
        tasks_completed: 3,
      },
    ];

    const periods = computeTimePeriodStats(summaries, 'week');

    expect(periods).toHaveLength(2);
    // Should have week numbers in format YYYY-Www
    for (const p of periods) {
      expect(p.period).toMatch(/^\d{4}-W\d{2}$/);
    }
  });
});

// ─── CLI Integration Tests ──────────────────────────────────────────────────

describe('kspec session log stats (CLI)', () => {
