    await fs.mkdir(s2Dir);
    await fs.writeFile(path.join(s2Dir, 'session.yaml'), YAML.stringify({
      id: s2,
      agent_type: 'custom-agent',
      status: 'active',
      started_at: '2026-02-01T08:00:00.000Z',
    }));
    await fs.writeFile(path.join(s2Dir, 'events.jsonl'), [
      JSON.stringify({
        ts: 5000,
        seq: 0,
