      expect(result).toHaveProperty('session_id');
      expect(result).toHaveProperty('agent_type');
      expect(result).toHaveProperty('started_at');
      expect(result).toHaveProperty('matches');
      expect(Array.isArray(result.matches)).toBe(true);
    }
