          description: options.description,
          depends_on: [],
          implements: [],
          relates_to: [],
          tests: [],
          traits: [],
          notes: [],
        };

        const newItem = createSpecItem(input);
        const result = await addChildItem(ctx, parent, newItem, options.as);

