        if (!slugCheck.ok) {
          error(
            errors.slug.alreadyExists(slugCheck.slug, slugCheck.existingUlid),
          );
          process.exit(EXIT_CODES.CONFLICT);
        }
      }

      // Validate --remove-slug
      if (options.removeSlug) {
