                    : chalk.gray;
              const shortId = task.taskUlid.slice(0, 8);
              const notes = task.hasNotes ? chalk.gray(" (has notes)") : "";
              console.log(
                `  ${statusColor(`[${task.taskStatus}]`)} ${shortId} ${task.taskTitle}${notes}`,
              );
